// Contextual help per circuit (page). Shown by the floating "?" button (PageHelp) and
// mirrored in docs/USER_MANUAL.md. Keep entries short, practical and in Greek.

export type Help = {
  title: string;
  title_en?: string;
  /** Μία γραμμή: σε τι χρησιμεύει η οθόνη. */
  intro: string;
  intro_en?: string;
  /** ΠΩΣ ΔΟΥΛΕΥΕΙ — ο μηχανισμός από πίσω: τι συμβαίνει, με ποιον κανόνα, τι δεν κάνει μόνο του.
   *  Χωρίς αυτό ο χρήστης ξέρει ποιο κουμπί να πατήσει, αλλά όχι τι θα γίνει μετά. */
  logic?: string;
  logic_en?: string;
  /** ΠΩΣ ΤΟ ΚΑΝΕΙΣ — αριθμημένα βήματα, με τα ΟΝΟΜΑΤΑ που βλέπει στην οθόνη. */
  how?: string[];
  how_en?: string[];
  /** Προαιρετικό γλωσσάρι όρων της οθόνης — μόνο όπου η ορολογία δεν είναι προφανής. */
  what?: { label: string; desc: string; label_en?: string; desc_en?: string }[];
  tips?: string[];
  tips_en?: string[];
  /** Ο τίτλος της αντίστοιχης ενότητας στο Εγχειρίδιο (docs/USER_MANUAL.md).
   *  Το πάνελ δείχνει σύνδεσμο «Δες το στο Εγχειρίδιο» → /manual#<slug>. */
  manual?: string;
};

/** Ίδιος κανόνας με τη σελίδα /manual, ώστε τα #anchors να ταιριάζουν. */
export const manualSlug = (s: string) =>
  s.toLowerCase().replace(/[*`_]/g, "").replace(/[^\p{L}\p{N}]+/gu, "-").replace(/^-|-$/g, "");

